import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

/**
 * CLI: `npm run vendor`
 * Copies Chart.js and the Vazirmatn webfonts from node_modules into
 * `public/vendor` so the application never contacts a CDN at runtime.
 */
const rootDir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const vendorDir = path.join(rootDir, 'public', 'vendor');
const fontsDir = path.join(vendorDir, 'fonts');
const cssOut = path.join(rootDir, 'public', 'css', 'vazirmatn.css');

const WEIGHTS = [400, 500, 600, 700, 800];
const SUBSETS = ['arabic', 'latin'];

function copyChart() {
  const source = path.join(rootDir, 'node_modules', 'chart.js', 'dist', 'chart.umd.min.js');
  if (!fs.existsSync(source)) throw new Error(`Chart.js not found at ${source}. Run "npm install" first.`);
  let code = fs.readFileSync(source, 'utf8');
  code = code.replace(/\/\/# sourceMappingURL=.*\s*$/u, '');
  fs.writeFileSync(path.join(vendorDir, 'chart.umd.js'), code);
  return fs.statSync(path.join(vendorDir, 'chart.umd.js')).size;
}

function copyFonts() {
  fs.mkdirSync(fontsDir, { recursive: true });
  const blocks = [];
  const copied = new Set();

  for (const subset of SUBSETS) {
    for (const weight of WEIGHTS) {
      const cssFile = path.join(rootDir, 'node_modules', '@fontsource', 'vazirmatn', `${subset}-${weight}.css`);
      if (!fs.existsSync(cssFile)) throw new Error(`Font CSS not found: ${cssFile}`);
      let css = fs.readFileSync(cssFile, 'utf8');

      // Keep only the woff2 source, then point it at the vendored copy.
      css = css.replace(/,\s*url\(([^)]+\.woff)\)\s*format\(['"]woff['"]\)/g, '');

      for (const match of css.matchAll(/url\(([^)]+)\)/g)) {
        const raw = match[1].replace(/['"]/g, '').trim();
        const fileName = path.basename(raw);
        if (copied.has(fileName)) continue;
        const src = path.join(rootDir, 'node_modules', '@fontsource', 'vazirmatn', 'files', fileName);
        if (!fs.existsSync(src)) continue;
        fs.copyFileSync(src, path.join(fontsDir, fileName));
        copied.add(fileName);
      }

      css = css.replace(/url\(([^)]+)\)/g, (_all, raw) => {
        const trimmed = raw.replace(/['"]/g, '').trim();
        return `url('/vendor/fonts/${path.basename(trimmed)}')`;
      });
      blocks.push(css.trim());
    }
  }

  const header = `/* Generated by scripts/vendor.js - do not edit by hand. */\n/* Vazirmatn (SIL Open Font License 1.1) vendored locally. */\n\n`;
  fs.mkdirSync(path.dirname(cssOut), { recursive: true });
  fs.writeFileSync(cssOut, header + blocks.join('\n\n') + '\n');
  return { files: copied.size, bytes: fs.statSync(cssOut).size };
}

fs.mkdirSync(vendorDir, { recursive: true });
const chartBytes = copyChart();
const fonts = copyFonts();

console.log(JSON.stringify({
  chart: { file: 'public/vendor/chart.umd.js', bytes: chartBytes },
  fonts: { dir: 'public/vendor/fonts', files: fonts.files, css: 'public/css/vazirmatn.css' },
}, null, 2));
